namespace Ehr.Data.Patients;

// A patient's demographics: the first PHI table, and the one every other PHI table will hang off. Row-level security
// is enabled and forced on it and every write is recorded by trigger (db/policies); reads go through the PHI reader
// in Ehr.Domain, which records them. Synthetic data only.
public class Patient
{
    // UUIDv7, generated by whoever creates the row.
    public Guid Id { get; set; }

    // The medical record number clinicians see and search by. Unique in the clinic.
    public required string Mrn { get; set; }

    public required string GivenName { get; set; }

    public required string FamilyName { get; set; }

    public DateOnly BirthDate { get; set; }

    // One of AdministrativeGender.
    public required string Gender { get; set; }

    // Goes up by one on every update. A save that started from an older version is a conflict.
    public int Version { get; set; } = 1;

    public DateTimeOffset UpdatedAt { get; set; }
}
